                      </div>
                      <div className="space-y-1">
                        <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-3">Catégorie</label>
                        <select className="w-full p-5 bg-gray-50 rounded-2xl font-bold outline-none border-2 border-transparent focus:border-brand-orange text-sm shadow-inner appearance-none" value={formData.category} onChange={e=>setFormData({...formData, category: e.target.value as MenuCategory})}>
                            {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                      </div>
                      <button type="submit" className="w-full bg-brand-brown text-white py-6 rounded-[2rem] font-black shadow-2xl hover:bg-brand-orange transition-all flex items-center justify-center gap-2 active:scale-95 uppercase tracking-widest mt-4 text-xs border-4 border-white">
                        <Save size={20}/> Confirmer l'enregistrement
                      </button>
                  </form>
              </div>
          </div>
      )}
    </div>
  );
};

