import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, Utensils, ClipboardList, Brain, 
  Bell, Package, Menu, X, Lock, 
  Camera, Plus, Trash2, Edit3, Image, Save, Crown, TrendingUp,
  ChefHat, Settings, Users, Send, Sparkles, Lightbulb, Star
} from 'lucide-react';
import { MenuItem, AdminView, MenuCategory } from '../types';
import { playSound } from '../utils/audio';
import { getAdminInsights } from '../services/geminiService';

interface AdminDashboardProps {
  items: MenuItem[];
  setItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  onExit: () => void;
  adminPhoto: string | null;
  setAdminPhoto: (photo: string | null) => void;
  loyaltyConfig: { pointsPerFranc: number; rewardThreshold: number };
  setLoyaltyConfig: (config: any) => void;
}

const CATEGORIES: MenuCategory[] = ['Plat Africain', 'Plat Européen', 'Spécialité Maison', 'Box', 'Entree', 'Dessert', 'Boisson'];

const AdminDashboard: React.FC<AdminDashboardProps> = ({ items, setItems, onExit, adminPhoto, setAdminPhoto, loyaltyConfig, setLoyaltyConfig }) => {
  const [currentView, setCurrentView] = useState<AdminView>(AdminView.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [formData, setFormData] = useState<Partial<MenuItem>>({
      name: '', description: '', price: 0, category: 'Plat Africain', image: '', isAvailable: true
  });

  // IA Strategy States
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'admin' | 'item') => {
      if (e.target.files && e.target.files[0]) {
          const reader = new FileReader();
          reader.onload = (event) => {
              const data = event.target?.result as string;
              if (type === 'admin') {
                  setAdminPhoto(data);
                  localStorage.setItem('admin_photo_profile', data);
              }
              else setFormData(prev => ({ ...prev, image: data }));
              playSound('success');
          };
          reader.readAsDataURL(e.target.files[0]);
      }
  };

  const askAI = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    const result = await getAdminInsights(aiQuery, { items_count: items.length, top_dishes: items.slice(0,3).map(i => i.name) });
    setAiResponse(result);
    setIsAiLoading(false);
    playSound('cash');
  };

  const handleSaveItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingItem) {
      setItems(prev => prev.map(i => i.id === editingItem.id ? { ...i, ...formData } as MenuItem : i));
    } else {
      const newItem: MenuItem = {
        id: Date.now().toString(),
