                                  <p className="text-brand-orange font-black">{item.price} F</p>
                               </div>
                               <div className="flex flex-col gap-2">
                                   <button onClick={() => { setEditingItem(item); setFormData({...item}); setIsModalOpen(true); }} className="p-3 bg-gray-50 text-brand-brown rounded-xl"><Edit3 size={16}/></button>
                                   <button onClick={() => { if(confirm('Supprimer ?')) setItems(prev => prev.filter(i => i.id !== item.id)); }} className="p-3 bg-red-50 text-red-500 rounded-xl"><Trash2 size={16}/></button>
                               </div>
                           </div>
                       ))}
                   </div>
              </div>
          )}
      </div>

      {isModalOpen && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/95 backdrop-blur-xl">
              <div className="bg-white rounded-[3.5rem] w-full max-w-md overflow-hidden shadow-2xl">
                  <form onSubmit={handleSaveItem} className="p-10 space-y-6">
                      <h3 className="font-black text-brand-brown uppercase tracking-widest text-center">{editingItem ? 'Modifier' : 'Ajouter'} un Plat</h3>
                      <input required type="text" placeholder="Nom du plat" className="w-full p-6 bg-gray-50 rounded-3xl font-black text-sm" value={formData.name} onChange={e=>setFormData({...formData, name: e.target.value})} />
                      <input required type="number" placeholder="Prix" className="w-full p-6 bg-gray-50 rounded-3xl font-black text-sm" value={formData.price} onChange={e=>setFormData({...formData, price: Number(e.target.value)})} />
                      <button type="submit" className="w-full bg-brand-brown text-white py-6 rounded-3xl font-black uppercase tracking-widest flex items-center justify-center gap-2">
                        <Save size={20}/> Sauvegarder
                      </button>
                  </form>
              </div>
          </div>
      )}
    </div>
  );
};

