} from 'lucide-react';
import { MenuItem, AdminView, MenuCategory } from '../types';
import { playSound } from '../utils/audio';
import { getAdminInsights } from '../services/geminiService';

interface AdminDashboardProps {
  items: MenuItem[];
  setItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  onExit: () => void;
  adminPhoto: string | null;
  setAdminPhoto: (photo: string | null) => void;
  loyaltyConfig: { pointsPerFranc: number; rewardThreshold: number };
  setLoyaltyConfig: (config: any) => void;
}

const CATEGORIES: MenuCategory[] = ['Plat Africain', 'Plat Européen', 'Spécialité Maison', 'Box', 'Entree', 'Dessert', 'Boisson'];

const AdminDashboard: React.FC<AdminDashboardProps> = ({ items, setItems, onExit, adminPhoto, setAdminPhoto, loyaltyConfig, setLoyaltyConfig }) => {
  const [currentView, setCurrentView] = useState<AdminView>(AdminView.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [formData, setFormData] = useState<Partial<MenuItem>>({
      name: '', description: '', price: 0, category: 'Plat Africain', image: '', isAvailable: true
  });

  // IA Strategy States
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'admin' | 'item') => {
      if (e.target.files && e.target.files[0]) {
          const reader = new FileReader();
          reader.onload = (event) => {
              const data = event.target?.result as string;
              if (type === 'admin') {
                  setAdminPhoto(data);
                  localStorage.setItem('admin_photo_profile', data);
              }
              else setFormData(prev => ({ ...prev, image: data }));
              playSound('success');
          };
          reader.readAsDataURL(e.target.files[0]);
      }
  };

  const askAI = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    const result = await getAdminInsights(aiQuery, { items_count: items.length, top_dishes: items.slice(0,3).map(i => i.name) });
    setAiResponse(result);
    setIsAiLoading(false);
    playSound('cash');
  };

  const handleSaveItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingItem) {
      setItems(prev => prev.map(i => i.id === editingItem.id ? { ...i, ...formData } as MenuItem : i));
    } else {
      const newItem: MenuItem = {
        id: Date.now().toString(),
        name: formData.name || '',
        description: formData.description || '',
        price: formData.price || 0,
        image: formData.image || '',
        category: (formData.category as MenuCategory) || 'Plat Africain',
        rating: 5,
        isAvailable: true,
      };
      setItems(prev => [...prev, newItem]);
    }
    setIsModalOpen(false);
    setEditingItem(null);
    playSound('success');
  };

  const navItems = [
    { view: AdminView.DASHBOARD, icon: LayoutDashboard, label: 'Tableau de bord' },
    { view: AdminView.PLATS, icon: Utensils, label: 'Menu & Plats' },
    { view: AdminView.BOX, icon: Package, label: 'Gestion Box' },
    { view: AdminView.COMMANDE, icon: ClipboardList, label: 'Commandes' },
    { view: AdminView.LOYALTY, icon: Crown, label: 'Fidélité' },
    { view: AdminView.AI, icon: Brain, label: 'Stratégie IA' },
    { view: AdminView.SETTINGS, icon: Settings, label: 'Réglages' },
  ];

  return (
    <div className="min-h-screen bg-[#FDFCFB] flex flex-col font-sans">
      {/* Sidebar Mobile */}
      {isSidebarOpen && <div className="fixed inset-0 bg-black/80 z-40 backdrop-blur-md" onClick={() => setIsSidebarOpen(false)}></div>}
      <div className={`fixed top-0 left-0 h-full w-72 bg-gradient-to-b from-[#1A0F0D] to-[#3E2723] text-white z-50 transform transition-transform duration-500 shadow-[10px_0_50px_rgba(0,0,0,0.3)] ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-8 border-b border-white/5 text-center relative overflow-hidden">
            <div className="absolute -top-10 -right-10 w-32 h-32 bg-brand-orange/10 rounded-full blur-3xl"></div>
            <h2 className="text-2xl font-black mb-8 tracking-tighter uppercase italic">Khady's <span className="text-brand-orange">Pro</span></h2>

            <div className="relative group w-28 h-28 mx-auto mb-4">
                <div className="absolute inset-0 bg-brand-gold rounded-full animate-pulse opacity-20"></div>
                <div className="relative w-full h-full rounded-full border-4 border-brand-orange/50 p-1 bg-[#1A0F0D] shadow-2xl overflow-hidden cursor-pointer group">
                    <img src={adminPhoto || "https://images.unsplash.com/photo-1583394293214-28ded15ee548?q=80&w=200&auto=format&fit=crop"} className="w-full h-full object-cover rounded-full" alt="Gérant" />
                    <label className="absolute inset-0 bg-black/60 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                        <Camera size={20} className="text-white"/>
                        <input type="file" className="hidden" onChange={(e)=>handleImageUpload(e, 'admin')}/>
                    </label>
                </div>
