import React, { useState, useEffect } from 'react';
import { DISTRICTS, BILLO_LOGO_URL, DELIVERY_TIME, BILLO_INFO } from '../constants';
import { Clock, MapPin, Bike, AlertCircle } from 'lucide-react';
import { District } from '../types';

const DeliveryEstimator: React.FC = () => {
  const [selectedDistrict, setSelectedDistrict] = useState<string>('');
  const [time, setTime] = useState<string>('');
  const [price, setPrice] = useState<number | null>(null);

  useEffect(() => {
    const now = new Date();
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    setTime(`${hours}:${minutes}`);
  }, []);

  const calculate = () => {
    if (!selectedDistrict || !time) return;
    const district = DISTRICTS.find(d => d.name === selectedDistrict);
    if (!district) return;

    const hour = parseInt(time.split(':')[0]);
    const isNight = hour >= 21 || hour < 6;

    let calculatedPrice = 0;
    if (district.zone === 'center') {
      calculatedPrice = isNight ? 1500 : 1000;
    } else {
      calculatedPrice = isNight ? 2000 : 1500;
    }
    setPrice(calculatedPrice);
  };

  useEffect(() => {
    calculate();
  }, [selectedDistrict, time]);

  return (
    <div className="bg-white rounded-[3rem] shadow-2xl p-8 mb-6 border border-brand-brown/5 relative overflow-hidden">
      <div className="absolute top-0 right-0 w-32 h-32 bg-brand-orange/5 rounded-full -mr-16 -mt-16"></div>

      <div className="flex items-center space-x-5 mb-8 relative z-10">
        <div className="w-16 h-16 rounded-[1.5rem] border-2 border-brand-orange bg-white p-1.5 shadow-xl flex items-center justify-center overflow-hidden">
            <img src={BILLO_LOGO_URL} alt="Billo Express" className="w-full h-full object-contain" />
        </div>
        <div>
          <h3 className="font-black text-brand-brown uppercase tracking-tighter text-lg italic">{BILLO_INFO.name}</h3>
          <p className="text-[10px] text-brand-orange font-black uppercase tracking-[0.2em]">Partenaire Livraison</p>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 mb-8">
        <div className="space-y-2">
          <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-1 ml-2">
            <MapPin size={10} /> Zone
          </label>
          <select 
            value={selectedDistrict}
            onChange={(e) => setSelectedDistrict(e.target.value)}
            className="w-full text-xs p-5 bg-gray-50 rounded-3xl border-none focus:ring-1 focus:ring-brand-orange font-bold shadow-inner appearance-none"
          >
            <option value="">Quartier...</option>
            {DISTRICTS.map(d => (
              <option key={d.name} value={d.name}>{d.name}</option>
            ))}
          </select>
        </div>

        <div className="space-y-2">
          <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-1 ml-2">
            <Clock size={10} /> Heure
          </label>
          <input 
            type="time" 
            value={time}
            onChange={(e) => setTime(e.target.value)}
            className="w-full text-xs p-5 bg-gray-50 rounded-3xl border-none focus:ring-1 focus:ring-brand-orange font-bold shadow-inner"
          />
        </div>
      </div>

      <div className="bg-orange-50/50 p-5 rounded-[2rem] border border-orange-100 flex items-start gap-3 mb-6">
          <AlertCircle size={18} className="text-brand-orange flex-shrink-0 mt-0.5" />
          <p className="text-[9px] font-bold text-brand-orange leading-tight italic uppercase tracking-widest">{BILLO_INFO.fridayRule}</p>
      </div>

      {price !== null && (
        <div className="p-6 bg-[#1A0F0D] text-brand-gold rounded-[2.5rem] flex justify-between items-center animate-slide-up shadow-2xl border-4 border-white">
          <div className="flex flex-col">
            <span className="text-[8px] font-black uppercase tracking-widest text-white/50 mb-1">Tarif Livraison</span>
            <span className="text-2xl font-black italic">{price} CFA</span>
          </div>
          <div className="flex flex-col items-end">
             <span className="text-[8px] font-black uppercase tracking-widest text-white/50 mb-1">Délai Estimé</span>
             <span className="text-xs font-black text-white">{DELIVERY_TIME}</span>
          </div>
        </div>
      )}
    </div>
  );
};

