                            <input required type="number" placeholder="Prix (CFA)" className="w-full p-6 bg-white/5 rounded-3xl font-black text-sm outline-none border border-white/5 focus:border-brand-orange text-white shadow-inner" value={formData.price} onChange={e=>setFormData({...formData, price: Number(e.target.value)})} />
                            <select className="w-full p-6 bg-white/5 rounded-3xl font-black text-xs outline-none border border-white/5 focus:border-brand-orange text-white shadow-inner appearance-none" value={formData.category} onChange={e=>setFormData({...formData, category: e.target.value as MenuCategory})}>
                                {CATEGORIES.map(c => <option key={c} value={c} className="bg-[#161616]">{c}</option>)}
                            </select>
                        </div>
                      </div>

                      <div className="flex gap-4 pt-4">
                        <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 bg-white/5 text-white/40 py-6 rounded-[2rem] font-black uppercase text-[10px] tracking-widest hover:bg-white/10 transition-all border border-white/5">Annuler</button>
                        <button type="submit" className="flex-[2] bg-brand-orange text-white py-6 rounded-[2rem] font-black uppercase tracking-widest shadow-2xl flex items-center justify-center gap-2 hover:bg-orange-600 transition-all active:scale-95">
                            <Save size={20}/> Valider
                        </button>
                      </div>
                  </form>
              </div>
          </div>
      )}
    </div>
  );
};

