                           <input required type="password" placeholder="Code Secret" className="w-full p-5 bg-gray-50 rounded-[2rem] font-black text-sm shadow-inner" value={userAuthData.password} onChange={e => setUserAuthData({...userAuthData, password: e.target.value})} />
