import React, { useState } from 'react';
import { MenuItem } from '../types';
import { X, Plus, Minus, MessageSquare, Flame, Leaf, Star, CheckCircle2, Clock, ShieldCheck } from 'lucide-react';

interface ItemDetailsModalProps {
  item: MenuItem | null;
  isOpen: boolean;
  onClose: () => void;
  onAddToCart: (item: MenuItem, quantity: number, instructions: string) => void;
}

const ItemDetailsModal: React.FC<ItemDetailsModalProps> = ({ item, isOpen, onClose, onAddToCart }) => {
  const [quantity, setQuantity] = useState(1);
  const [instructions, setInstructions] = useState('');

  if (!isOpen || !item) return null;

  const handleAdd = () => {
    onAddToCart(item, quantity, instructions);
    setQuantity(1);
    setInstructions('');
    onClose();
  };

  const isPack = item.category === 'Pack';

  return (
    <div className="fixed inset-0 z-[80] flex items-end sm:items-center justify-center bg-black/60 backdrop-blur-sm animate-fade-in" onClick={onClose}>
      <div 
        className="bg-white w-full sm:w-[400px] h-[90vh] sm:h-auto sm:rounded-3xl rounded-t-[2rem] shadow-2xl overflow-hidden flex flex-col relative animate-slide-up"
        onClick={e => e.stopPropagation()}
      >
        <div className="relative h-64 w-full">
            <img src={item.image} alt={item.name} className="w-full h-full object-cover" />
            <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent"></div>

            {/* Tag Badges on Image */}
            <div className="absolute top-4 left-4 flex flex-wrap gap-2">
               {item.isPlatDuJour && (
                 <div className="bg-yellow-500 text-white px-3 py-1 rounded-full text-[10px] font-black flex items-center gap-1 shadow-lg border border-white/20">
                    <CheckCircle2 size={12} /> Plat du Jour
                 </div>
               )}
               {item.isSpicy && (
                 <div className="bg-red-500 text-white px-3 py-1 rounded-full text-[10px] font-black flex items-center gap-1 shadow-lg border border-white/20">
                    <Flame size={12} /> Épicé
                 </div>
               )}
               {item.isVegetarian && (
                 <div className="bg-green-500 text-white px-3 py-1 rounded-full text-[10px] font-black flex items-center gap-1 shadow-lg border border-white/20">
                    <Leaf size={12} /> Végétarien
                 </div>
               )}
            </div>

            <button onClick={onClose} className="absolute top-4 right-4 bg-black/30 backdrop-blur-md text-white p-2 rounded-full hover:bg-black/50 transition-colors"><X size={24} /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 bg-white -mt-6 rounded-t-[2rem] relative z-10">
            <div className="flex justify-between items-start mb-4">
                <h2 className="text-2xl font-black text-brand-brown leading-tight w-3/4 italic uppercase tracking-tighter">{item.name}</h2>
                <div className="text-right">
                  <span className="text-xl font-black text-brand-orange block">{item.price} F</span>
                  {isPack && <span className="text-[8px] font-bold text-gray-400 uppercase tracking-widest">Dès 5 pers.</span>}
                </div>
            </div>

            <p className="text-gray-500 text-sm mb-6 leading-relaxed italic">"{item.description}"</p>

            {/* Pack Specific Conditions */}
            {isPack && (
              <div className="bg-brand-brown p-5 rounded-[1.5rem] mb-6 space-y-3">
                 <div className="flex items-center gap-3 text-brand-gold">
                    <Clock size={16} />
                    <p className="text-[10px] font-black uppercase tracking-widest">Précommande 1 semaine minimum</p>
                 </div>
                 <div className="flex items-center gap-3 text-brand-gold">
                    <ShieldCheck size={16} />
                    <p className="text-[10px] font-black uppercase tracking-widest">Acompte de 75% à la commande</p>
                 </div>
              </div>
            )}

            <div className="mb-6">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 flex items-center gap-2"><MessageSquare size={14} /> Instructions Spéciales</label>
                <textarea className="w-full bg-gray-50 border-none rounded-2xl p-4 text-sm text-gray-700 resize-none font-medium shadow-inner" placeholder="Ex: Sans piment, beaucoup d'allocos..." rows={3} value={instructions} onChange={(e) => setInstructions(e.target.value)}></textarea>
            </div>
        </div>

        <div className="p-4 border-t border-gray-100 bg-white shadow-2xl">
            <div className="flex items-center gap-4">
                <div className="flex items-center gap-4 bg-gray-100 rounded-2xl px-4 py-3">
                    <button onClick={() => setQuantity(Math.max(1, quantity - 1))} className="w-8 h-8 flex items-center justify-center bg-white rounded-xl shadow-sm text-gray-600 active:scale-90 transition-transform"><Minus size={16} /></button>
                    <span className="font-black text-xl w-6 text-center text-brand-brown">{quantity}</span>
                    <button onClick={() => setQuantity(quantity + 1)} className="w-8 h-8 flex items-center justify-center bg-brand-brown text-white rounded-xl shadow-sm active:scale-90 transition-transform"><Plus size={16} /></button>
                </div>
                <button onClick={handleAdd} className="flex-1 bg-brand-orange text-white py-4 rounded-2xl font-black text-lg shadow-lg active:scale-95 transition-transform flex flex-col items-center justify-center leading-none">
                    <span>Ajouter</span>
                    <span className="text-[10px] opacity-90 font-medium mt-1 italic">{(item.price * quantity)} F</span>
                </button>
            </div>
        </div>
      </div>
    </div>
  );
};

