import React, { useState } from 'react';
import { MenuItem } from '../types';
import { X, Plus, Minus, MessageSquare, Flame, Leaf, CheckCircle2, Clock, ShieldCheck, Users, Info } from 'lucide-react';

interface ItemDetailsModalProps {
  item: MenuItem | null;
  isOpen: boolean;
  onClose: () => void;
  onAddToCart: (item: MenuItem, quantity: number, instructions: string) => void;
}

const ItemDetailsModal: React.FC<ItemDetailsModalProps> = ({ item, isOpen, onClose, onAddToCart }) => {
  const [quantity, setQuantity] = useState(1);
  const [instructions, setInstructions] = useState('');

  if (!isOpen || !item) return null;

  const handleAdd = () => {
    onAddToCart(item, quantity, instructions);
    setQuantity(1);
    setInstructions('');
    onClose();
  };

  const isPack = item.category === 'Pack';

  return (
    <div className="fixed inset-0 z-[80] flex items-end sm:items-center justify-center bg-black/70 backdrop-blur-sm animate-fade-in" onClick={onClose}>
      <div 
        className="bg-white w-full sm:w-[420px] h-[92vh] sm:h-auto sm:max-h-[85vh] sm:rounded-[3rem] rounded-t-[3rem] shadow-2xl overflow-hidden flex flex-col relative animate-slide-up"
        onClick={e => e.stopPropagation()}
      >
        <div className="relative h-72 w-full flex-shrink-0">
            <img src={item.image} alt={item.name} className="w-full h-full object-cover" />
            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent"></div>

            <div className="absolute top-6 left-6 flex flex-wrap gap-2">
               {isPack && (
                 <div className="bg-brand-brown text-brand-gold px-4 py-1.5 rounded-full text-[10px] font-black flex items-center gap-2 shadow-xl border border-brand-gold/30">
                    <Users size={12} /> Dès {item.minPeople || 5} personnes
                 </div>
               )}
               {item.isPlatDuJour && (
                 <div className="bg-yellow-500 text-white px-3 py-1.5 rounded-full text-[10px] font-black flex items-center gap-1 shadow-lg">
                    <CheckCircle2 size={12} /> Plat du Jour
                 </div>
               )}
            </div>

            <button onClick={onClose} className="absolute top-6 right-6 bg-black/40 backdrop-blur-lg text-white p-2.5 rounded-full hover:bg-black/60 transition-colors shadow-lg"><X size={24} /></button>

            <div className="absolute bottom-8 left-8 right-8">
               <h2 className="text-3xl font-black text-white leading-none italic uppercase tracking-tighter mb-2">{item.name}</h2>
               <div className="flex items-center justify-between">
                  <span className="text-2xl font-black text-brand-gold">{item.price} CFA</span>
                  {item.isSpicy && <span className="bg-red-500/20 text-red-500 p-2 rounded-xl backdrop-blur-md"><Flame size={20} /></span>}
                  {item.isVegetarian && <span className="bg-green-500/20 text-green-500 p-2 rounded-xl backdrop-blur-md"><Leaf size={20} /></span>}
               </div>
            </div>
        </div>

        <div className="flex-1 overflow-y-auto p-8 bg-white rounded-t-[3rem] -mt-6 relative z-10 no-scrollbar">
            {/* Description principale */}
            <p className="text-gray-500 text-sm mb-8 leading-relaxed italic font-medium">"{item.description}"</p>

            {/* Détails spécifiques pour les PACKS */}
            {isPack && (
              <div className="space-y-8 mb-8 animate-fade-in">
                {/* Liste des inclusions */}
                <div>
                  <h4 className="text-[10px] font-black text-brand-brown uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                    <span className="w-6 h-6 bg-brand-orange/10 rounded-lg flex items-center justify-center text-brand-orange"><Plus size={12}/></span>
                    Composition du Pack
                  </h4>
                  <div className="bg-brand-cream/30 p-6 rounded-[2rem] border border-brand-brown/5 space-y-3">
                    {item.includes?.map((inc, i) => (
                      <div key={i} className="flex items-center gap-3">
                        <div className="w-1.5 h-1.5 bg-brand-orange rounded-full"></div>
                        <span className="text-xs font-bold text-brand-brown/80">{inc}</span>
                      </div>
                    )) || (
                      <p className="text-[10px] text-gray-400 italic">Composition variée selon le marché.</p>
                    )}
                  </div>
                </div>

                {/* Conditions de commande VISUELLES */}
                <div>
                   <h4 className="text-[10px] font-black text-brand-brown uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                    <span className="w-6 h-6 bg-brand-gold/10 rounded-lg flex items-center justify-center text-brand-gold"><Info size={12}/></span>
                    Conditions Obligatoires
                  </h4>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="bg-brand-brown p-5 rounded-[2rem] text-center shadow-xl border border-brand-gold/10">
                       <Clock className="text-brand-gold mx-auto mb-2" size={24} />
                       <p className="text-[9px] font-black text-white/50 uppercase mb-1">Délai</p>
                       <p className="text-[11px] font-black text-brand-gold uppercase">1 Semaine</p>
                    </div>
                    <div className="bg-brand-brown p-5 rounded-[2rem] text-center shadow-xl border border-brand-gold/10">
                       <ShieldCheck className="text-brand-gold mx-auto mb-2" size={24} />
                       <p className="text-[9px] font-black text-white/50 uppercase mb-1">Acompte</p>
                       <p className="text-[11px] font-black text-brand-gold uppercase">75% à Valider</p>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Section Instructions pour tout le monde */}
            <div className="mb-4">
                <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2 ml-2">
                  <MessageSquare size={14} className="text-brand-orange" /> 
                  Précisions ou Instructions
                </label>
                <textarea 
                  className="w-full bg-gray-50 border-2 border-transparent focus:border-brand-orange/20 rounded-[2rem] p-6 text-sm text-brand-brown font-medium resize-none shadow-inner outline-none transition-all" 
                  placeholder={isPack ? "Précisez l'événement, la date et l'heure..." : "Ex: Moins épicé, sans oignons..."} 
                  rows={3} 
                  value={instructions} 
                  onChange={(e) => setInstructions(e.target.value)}
                ></textarea>
            </div>
        </div>

        <div className="p-6 border-t border-gray-100 bg-white shadow-[0_-10px_30px_rgba(0,0,0,0.03)] flex-shrink-0">
            <div className="flex items-center gap-4">
                <div className="flex items-center gap-5 bg-gray-50 rounded-[2rem] px-5 py-3 border border-gray-100">
                    <button onClick={() => setQuantity(Math.max(1, quantity - 1))} className="w-10 h-10 flex items-center justify-center bg-white rounded-2xl shadow-sm text-brand-brown active:scale-90 transition-transform"><Minus size={18} /></button>
                    <span className="font-black text-2xl w-8 text-center text-brand-brown">{quantity}</span>
                    <button onClick={() => setQuantity(quantity + 1)} className="w-10 h-10 flex items-center justify-center bg-brand-brown text-white rounded-2xl shadow-sm active:scale-90 transition-transform"><Plus size={18} /></button>
                </div>
                <button onClick={handleAdd} className="flex-1 bg-brand-orange text-white py-5 rounded-[2.5rem] font-black text-lg shadow-2xl shadow-orange-200 active:scale-95 transition-all flex flex-col items-center justify-center leading-none">
                    <span className="uppercase tracking-tighter italic">Commander</span>
                    <span className="text-[10px] opacity-80 font-bold mt-1 uppercase tracking-widest italic">{(item.price * quantity).toLocaleString()} CFA</span>
                </button>
            </div>
        </div>
      </div>
    </div>
  );
};

