                    <p className="text-[10px] font-bold text-brand-orange uppercase tracking-[0.3em] mt-1">Vos commandes en temps réel</p>
                </header>
                <div className="text-center py-20 bg-white rounded-[4rem] shadow-inner border border-gray-50">
                    <div className="text-6xl mb-6">📦</div>
