                  <header className="flex flex-col items-center mb-6 text-center">
                    <div className="scale-110 mb-6"><KhadyLogo /></div>
                    <h2 className="text-2xl font-black text-brand-brown uppercase italic">Concept Digital</h2>
                  </header>
