      return (
        <AdminDashboard 
          items={items} 
          setItems={setItems} 
          reviews={reviews}
          setReviews={setReviews}
          onExit={() => setCurrentPage(Page.HOME)} 
          adminPhoto={adminPhoto} 
          setAdminPhoto={(p) => { setAdminPhoto(p); if(p) localStorage.setItem('admin_photo_profile', p); }} 
          adminPhone={adminPhone}
          setAdminPhone={(p) => { setAdminPhone(p); localStorage.setItem('admin_phone', p); }}
          loyaltyConfig={loyaltyConfig} 
          setLoyaltyConfig={setLoyaltyConfig} 
        />
      );
  }

  return (
    <div className="min-h-screen max-w-md mx-auto bg-gray-50 shadow-2xl overflow-hidden relative font-sans">
      <div className="h-full overflow-y-auto no-scrollbar scroll-smooth">{renderContent()}</div>
      <Navbar currentPage={currentPage} setPage={setCurrentPage} cartCount={cart.length} />
      <AIChat />
      <ItemDetailsModal item={selectedItemForDetails} isOpen={!!selectedItemForDetails} onClose={() => setSelectedItemForDetails(null)} onAddToCart={(item, qty, inst) => { setCart([...cart, {...item, quantity: qty, instructions: inst}]); playSound('success'); }} />
    </div>
  );
};

