              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-6">
                  {filteredItems.map(item => (
                      <div key={item.id} className="bg-white p-4 rounded-[3rem] shadow-xl border border-gray-50 flex flex-col group active:scale-95 hover:shadow-2xl transition-all duration-500 cursor-pointer" onClick={() => setSelectedItemForDetails(item)}>
