                      <p className="font-black text-brand-brown uppercase tracking-[0.2em] text-sm italic mb-4">Accès Protégé</p>
                      <p className="text-xs text-gray-500 font-medium leading-relaxed mb-10">Veuillez vous connecter à votre compte pour consulter l'historique et le statut de vos commandes.</p>
                      <button onClick={() => setCurrentPage(Page.COMPTE)} className="w-full bg-brand-brown text-brand-gold py-6 rounded-[2rem] font-black uppercase text-xs tracking-widest shadow-2xl active:scale-95 transition-all border-2 border-white/10">Aller à la connexion</button>
                  </div>
                ) : (
                  <div className="text-center py-24 bg-white rounded-[4rem] shadow-inner border border-gray-50 w-full">
                      <div className="text-7xl mb-10 animate-bounce">📦</div>
                      <p className="font-black text-brand-brown uppercase tracking-widest text-sm italic mb-2">Aucune commande en cours</p>
                      <p className="text-xs text-gray-400 mb-10">Faites vous plaisir dès maintenant !</p>
                      <button onClick={() => setCurrentPage(Page.MENU)} className="bg-brand-orange text-white px-12 py-5 rounded-[2rem] font-black uppercase text-[10px] tracking-widest shadow-2xl active:scale-95 transition-all">Parcourir le Menu</button>
                  </div>
                )}
