                        <h4 className="font-black text-[11px] uppercase tracking-widest text-brand-brown mb-6 italic flex items-center gap-3">Notre Histoire</h4>
                        <p className="text-sm text-gray-600 leading-relaxed font-medium italic">
                          {RESTAURANT_INFO.description}
