                  </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {items.filter(i => i.category === 'Pack').map(item => (
                   <div key={item.id} className="bg-white rounded-[4rem] shadow-2xl overflow-hidden border border-brand-brown/5 flex flex-col group cursor-pointer hover:shadow-orange-100 transition-all duration-500" onClick={() => setSelectedItemForDetails(item)}>
                      <div className="h-60 relative overflow-hidden">
                         <img src={item.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" />
                         <div className="absolute top-6 right-6 bg-brand-brown text-brand-gold px-6 py-3 rounded-[1.5rem] font-black text-sm shadow-2xl border-2 border-white/10">{item.price.toLocaleString()} CFA</div>
                      </div>
                      <div className="p-10">
                         <h3 className="font-black text-2xl text-brand-brown uppercase mb-3 leading-tight">{item.name}</h3>
                         <p className="text-xs text-gray-500 italic mb-8 leading-relaxed">Dès {item.minPeople} personnes. Inclus : {item.includes?.slice(0,3).join(', ')}...</p>
                         <button className="w-full bg-brand-brown text-brand-gold py-5 rounded-[1.5rem] font-black text-[10px] uppercase tracking-[0.2em] shadow-xl flex items-center justify-center gap-3 transition-colors hover:bg-brand-orange hover:text-white">Découvrir le Pack <ChevronRight size={18}/></button>
                      </div>
                   </div>
                ))}
              </div>
          </div>
        );
      default:
         return null;
    }
  };

  if (currentPage === Page.ADMIN) {
      return (
        <AdminDashboard 
          items={items} setItems={setItems} reviews={reviews} setReviews={setReviews} onExit={() => setCurrentPage(Page.HOME)} 
          adminPhoto={adminPhoto} setAdminPhoto={(p) => { setAdminPhoto(p); if(p) localStorage.setItem('admin_photo_profile', p); }} 
          adminPhone={adminPhone} setAdminPhone={(p) => { setAdminPhone(p); localStorage.setItem('admin_phone', p); }}
          loyaltyConfig={loyaltyConfig} setLoyaltyConfig={setLoyaltyConfig} 
        />
      );
  }

  return (
    <div className="min-h-screen bg-gray-50 shadow-2xl overflow-hidden relative font-sans flex flex-col items-center">
      <div className="flex-1 overflow-y-auto no-scrollbar scroll-smooth flex flex-col items-center w-full">
        <div className="w-full">{renderContent()}</div>
      </div>
      <Navbar currentPage={currentPage} setPage={setCurrentPage} cartCount={cart.length} />
      <AIChat />
      <ItemDetailsModal item={selectedItemForDetails} isOpen={!!selectedItemForDetails} onClose={() => setSelectedItemForDetails(null)} onAddToCart={(item, qty, inst) => { setCart([...cart, {...item, quantity: qty, instructions: inst}]); playSound('success'); }} />
    </div>
  );
};

