  const [adminPhone, setAdminPhone] = useState<string>(localStorage.getItem('admin_phone') || '+227 74 44 16 21');

  const [loyaltyConfig, setLoyaltyConfig] = useState({ pointsPerFranc: 0.1, rewardThreshold: 1000 });

  const [items, setItems] = useState<MenuItem[]>(MENU_ITEMS);
