  const [searchQuery, setSearchQuery] = useState('');
  const [activeCategory, setActiveCategory] = useState<MenuCategory | 'Tous'>('Tous');

  useEffect(() => {
    const timer = setTimeout(() => setShowSplash(false), 3000);
    return () => clearTimeout(timer);
  }, []);

  // Défilement automatique du carousel (Featured Index)
  useEffect(() => {
    const interval = setInterval(() => {
      setFeaturedIndex((prev) => (prev + 1) % 4);
    }, 6000);
    return () => clearInterval(interval);
  }, []);

  const handleAuthSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (userAuthData.password === ADMIN_PASSWORD) {
        playSound('success');
        setCurrentPage(Page.ADMIN);
        return;
    }
    if (userAuthData.phone) {
        setIsUserLoggedIn(true);
        playSound('success');
        setCurrentPage(Page.HOME);
    } else {
        alert("Numéro de téléphone requis.");
    }
  };

  const handleLogout = () => {
      setIsUserLoggedIn(false);
      setUserAuthData({ name: '', phone: '', password: '' });
      setCurrentPage(Page.HOME);
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.filter(item => item.id !== id));
    playSound('pop');
  };

