  const [isUserLoggedIn, setIsUserLoggedIn] = useState(false);
  const [userAuthData, setUserAuthData] = useState({ name: '', phone: '', password: '' });
  const [showPassword, setShowPassword] = useState(false);
  const [userPhoto, setUserPhoto] = useState<string | null>(null);
  const [adminPhoto, setAdminPhoto] = useState<string | null>(localStorage.getItem('admin_photo_profile'));
  const [adminPhone, setAdminPhone] = useState<string>(localStorage.getItem('admin_phone') || '+227 74 44 16 21');

  const [items, setItems] = useState<MenuItem[]>(MENU_ITEMS);
  const [reviews, setReviews] = useState<Review[]>(INITIAL_REVIEWS);
