                          <div key={item.id} className={`absolute inset-0 transition-all duration-1000 ease-in-out ${idx === featuredIndex ? 'opacity-100 scale-100' : 'opacity-0 scale-110'}`} onClick={() => setSelectedItemForDetails(item)}>
