  return (
    <div className="min-h-screen bg-gray-50 shadow-2xl overflow-hidden relative font-sans flex flex-col items-center">
      <div className="flex-1 overflow-y-auto no-scrollbar scroll-smooth flex flex-col items-center w-full">
