import React, { useState, useEffect, useRef } from 'react';
import { Home, Utensils, ShoppingCart, Package, Users, ChefHat, Info, User } from 'lucide-react';
import { Page } from '../types';
import { playSound } from '../utils/audio';

interface NavbarProps {
  currentPage: Page;
  setPage: (page: Page) => void;
  cartCount: number;
}

const Navbar: React.FC<NavbarProps> = ({ currentPage, setPage, cartCount }) => {
  const [isBouncing, setIsBouncing] = useState(false);
  const prevCount = useRef(cartCount);

  useEffect(() => {
    if (cartCount > prevCount.current) {
      setIsBouncing(true);
      const timer = setTimeout(() => setIsBouncing(false), 400);
      return () => clearTimeout(timer);
    }
    prevCount.current = cartCount;
  }, [cartCount]);

  const navItems = [
    { page: Page.HOME, icon: Home, label: 'Accueil' },
    { page: Page.MENU, icon: Utensils, label: 'Menu' },
    { page: Page.PACKS, icon: Users, label: 'Packs' },
    { page: Page.BOX, icon: Package, label: 'Box' },
    { page: Page.TRAITEUR, icon: ChefHat, label: 'Traiteur' },
    { page: Page.CART, icon: ShoppingCart, label: 'Panier', badge: cartCount, animate: true },
    { page: Page.COMPTE, icon: User, label: 'Compte' },
    { page: Page.PARAMETRES, icon: Info, label: 'Infos' },
  ];

  return (
    <nav className="fixed bottom-0 left-0 right-0 z-50 bg-white/98 backdrop-blur-lg border-t border-gray-100 shadow-[0_-4px_30px_rgba(0,0,0,0.05)] flex justify-around items-center h-20 px-0.5 pb-safe overflow-x-auto no-scrollbar">
        {navItems.map((item) => {
          const isActive = currentPage === item.page;
          const Icon = item.icon;
          const shouldAnimate = item.animate && isBouncing;

          return (
            <button 
              key={item.label} 
              onClick={() => { playSound('pop'); setPage(item.page); }} 
              className="relative flex flex-col items-center flex-shrink-0 w-[48px] transition-all group"
            >
              <div className={`p-1.5 rounded-xl transition-all duration-300 ${isActive ? 'bg-brand-orange text-white scale-110 shadow-lg shadow-orange-100' : 'text-gray-400 group-hover:text-brand-brown'} ${shouldAnimate ? 'animate-cart-pop' : ''}`}>
                <Icon size={17} strokeWidth={isActive ? 3 : 2} />
              </div>
              <span className={`text-[6px] font-black mt-1.5 uppercase tracking-tighter ${isActive ? 'text-brand-orange' : 'text-gray-400'}`}>
                {item.label}
              </span>
              {item.badge ? (
                <span className={`absolute top-1 right-2 bg-red-500 text-white text-[7px] font-black w-3.5 h-3.5 rounded-full flex items-center justify-center border border-white transition-transform duration-300 ${shouldAnimate ? 'scale-125' : 'scale-100'}`}>
                  {item.badge}
                </span>
              ) : null}
            </button>
          );
        })}
    </nav>
  );
};

