      {/* MODAL LAISSER UN AVIS CLIENT */}
      {isReviewModalOpen && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-xl animate-fade-in">
              <div className="bg-white rounded-[3rem] w-full max-w-sm p-10 shadow-2xl">
                  <div className="flex justify-between items-center mb-8">
                      <h3 className="text-xl font-black text-brand-brown uppercase italic">Votre Avis ✨</h3>
                      <button onClick={() => setIsReviewModalOpen(false)}><X/></button>
                  </div>
                  <form onSubmit={submitReview} className="space-y-6">
                      <div>
                          <label className="text-[10px] font-black uppercase text-gray-400 block mb-2">Note sur 5</label>
                          <div className="flex gap-2">
                              {[1,2,3,4,5].map(n => (
                                  <button key={n} type="button" onClick={() => setNewReview({...newReview, rating: n})} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${newReview.rating >= n ? 'bg-brand-orange text-white' : 'bg-gray-100 text-gray-400'}`}><Star size={20} fill={newReview.rating >= n ? "currentColor" : "none"} /></button>
                              ))}
                          </div>
                      </div>
                      <input required type="text" placeholder="Votre Prénom" className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold" value={newReview.name} onChange={e => setNewReview({...newReview, name: e.target.value})} />
                      <textarea required placeholder="Votre expérience culinaire..." className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold h-24 resize-none" value={newReview.comment} onChange={e => setNewReview({...newReview, comment: e.target.value})} />
                      <button type="submit" className="w-full bg-brand-brown text-brand-gold py-5 rounded-2xl font-black uppercase shadow-xl active:scale-95 transition-all">Publier mon avis</button>
                  </form>
              </div>
          </div>
      )}

      <ItemDetailsModal 
        item={selectedItemForDetails} 
        isOpen={!!selectedItemForDetails} 
        onClose={() => setSelectedItemForDetails(null)} 
        onAddToCart={(item, qty, inst) => { 
          setCart([...cart, {...item, quantity: qty, instructions: inst}]); 
          playSound('success'); 
        }} 
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, Utensils, ClipboardList, Brain, 
