} from 'lucide-react';
import { MenuItem, AdminView, MenuCategory, Review } from '../types';
import { playSound } from '../utils/audio';

interface AdminDashboardProps {
  items: MenuItem[];
  setItems: React.Dispatch<React.SetStateAction<MenuItem[]>>;
  reviews: Review[];
  setReviews: React.Dispatch<React.SetStateAction<Review[]>>;
  onExit: () => void;
  adminPhoto: string | null;
  setAdminPhoto: (photo: string | null) => void;
  adminPhone: string;
  setAdminPhone: (phone: string) => void;
  loyaltyConfig: { pointsPerFranc: number; rewardThreshold: number };
  setLoyaltyConfig: (config: any) => void;
}

const CATEGORIES: MenuCategory[] = ['Plat Africain', 'Plat Européen', 'Spécialité Maison', 'Box', 'Pack', 'Entree', 'Dessert', 'Boisson'];

const AdminDashboard: React.FC<AdminDashboardProps> = ({ items, setItems, reviews, setReviews, onExit, adminPhoto, setAdminPhoto, adminPhone, setAdminPhone, loyaltyConfig, setLoyaltyConfig }) => {
  const [currentView, setCurrentView] = useState<AdminView>(AdminView.DASHBOARD);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuItem | null>(null);
  const [filterCategory, setFilterCategory] = useState<MenuCategory | 'Tous'>('Tous');

  // États pour répondre aux avis
  const [replyingToReview, setReplyingToReview] = useState<Review | null>(null);
  const [replyText, setReplyText] = useState('');

  const [formData, setFormData] = useState<Partial<MenuItem>>({
      name: '', description: '', price: 0, category: 'Plat Africain', image: '', isAvailable: true,
      isPlatDuJour: false, isSpicy: false, isVegetarian: false, isPromo: false, isAnnulated: false
  });

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'admin' | 'item') => {
      if (e.target.files && e.target.files[0]) {
          const reader = new FileReader();
          reader.onload = (event) => {
              const data = event.target?.result as string;
              if (type === 'admin') setAdminPhoto(data);
              else setFormData(prev => ({ ...prev, image: data }));
          };
          reader.readAsDataURL(e.target.files[0]);
      }
  };

  const handleSaveItem = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingItem) {
      setItems(prev => prev.map(i => i.id === editingItem.id ? { ...i, ...formData } as MenuItem : i));
    } else {
      const newItem: MenuItem = {
        id: Date.now().toString(),
        name: formData.name || '',
        description: formData.description || '',
        price: formData.price || 0,
        image: formData.image || '',
        category: (formData.category as MenuCategory) || 'Plat Africain',
        rating: 5,
        isAvailable: true,
        ...formData
      };
      setItems(prev => [...prev, newItem]);
    }
    setIsModalOpen(false);
    playSound('success');
  };

  const submitReply = () => {
      if (!replyingToReview || !replyText.trim()) return;
      setReviews(prev => prev.map(r => r.id === replyingToReview.id ? { ...r, adminReply: replyText } : r));
      setReplyingToReview(null);
      setReplyText('');
      playSound('success');
  };

  const navItems = [
    { view: AdminView.DASHBOARD, icon: LayoutDashboard, label: 'Tableau de bord' },
    { view: AdminView.PLATS, icon: Utensils, label: 'Menu & Plats' },
    { view: AdminView.PACKS, icon: Users, label: 'Packs Groupe' },
    { view: AdminView.BOX, icon: Package, label: 'Gestion Box' },
    { view: AdminView.REVIEWS, icon: MessageSquare, label: 'Avis Clients' },
    { view: AdminView.AI, icon: Brain, label: 'Stratégie IA' },
    { view: AdminView.SETTINGS, icon: Settings, label: 'Réglages' },
  ];

  return (
    <div className="min-h-screen bg-[#1A0F0D] flex flex-col font-sans text-white">
      {/* Sidebar Mobile */}
      {isSidebarOpen && <div className="fixed inset-0 bg-black/95 z-40 backdrop-blur-xl" onClick={() => setIsSidebarOpen(false)}></div>}
      <div className={`fixed top-0 left-0 h-full w-72 bg-[#2A1916] text-white z-50 transform transition-transform duration-500 border-r border-white/5 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-8 border-b border-white/5 text-center">
            <h2 className="text-2xl font-black mb-8 tracking-tighter uppercase italic">Khady's <span className="text-brand-orange">Pro</span></h2>
            <div className="w-24 h-24 mx-auto mb-4 rounded-full border-2 border-brand-orange p-1 overflow-hidden">
                <img src={adminPhoto || "https://images.unsplash.com/photo-1583394293214-28ded15ee548?q=80&w=200&auto=format&fit=crop"} className="w-full h-full object-cover rounded-full" />
            </div>
            <p className="font-black text-[10px] text-brand-gold uppercase tracking-widest">ADMINISTRATEUR</p>
        </div>
        <div className="p-4 space-y-1">
            {navItems.map(item => (
                <button key={item.view} onClick={() => { setCurrentView(item.view); setIsSidebarOpen(false); }} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all ${currentView === item.view ? 'bg-brand-orange text-white' : 'text-white/30 hover:bg-white/5'}`}>
                    <item.icon size={20} /> <span className="font-bold text-[10px] uppercase tracking-widest">{item.label}</span>
                </button>
            ))}
        </div>
        <div className="absolute bottom-6 w-full px-6"><button onClick={onExit} className="w-full text-red-500 p-4 font-black text-[10px] uppercase tracking-widest bg-red-500/5 rounded-2xl">Déconnexion</button></div>
      </div>

      {/* Header */}
      <div className="bg-[#1A0F0D]/90 px-6 py-5 flex justify-between items-center shadow-2xl border-b border-white/5">
         <button onClick={() => setIsSidebarOpen(true)} className="p-3 bg-white/5 text-white rounded-2xl"><Menu size={22} /></button>
         <h1 className="font-black text-sm uppercase text-white">{navItems.find(n => n.view === currentView)?.label}</h1>
      </div>

      {/* Content */}
      <div className="p-6 flex-1 overflow-y-auto no-scrollbar pb-24">
          {currentView === AdminView.REVIEWS && (
              <div className="animate-fade-in space-y-8">
                  <div className="bg-white/5 p-8 rounded-[3rem] border border-white/5">
                      <h3 className="text-xl font-black uppercase italic mb-2">Gestion des Avis</h3>
                      <p className="text-[10px] font-bold text-white/30 uppercase tracking-widest">Répondez et modérez les témoignages clients</p>
                  </div>

                  <div className="grid grid-cols-1 gap-6">
                      {reviews.map(review => (
                          <div key={review.id} className="bg-white/5 p-8 rounded-[3rem] border border-white/5 shadow-xl">
                              <div className="flex justify-between items-start mb-6">
                                  <div className="flex gap-4">
                                      <img src={review.image} className="w-14 h-14 rounded-full border-2 border-brand-orange object-cover" />
                                      <div>
                                          <h4 className="font-black text-xs uppercase text-white">{review.name}</h4>
                                          <div className="flex gap-0.5 mt-1">{[...Array(review.rating)].map((_, i) => <Star key={i} size={10} fill="#FFD700" color="#FFD700" />)}</div>
                                      </div>
                                  </div>
                                  <button onClick={() => setReviews(prev => prev.filter(r => r.id !== review.id))} className="p-3 text-red-500 bg-red-500/10 rounded-2xl"><Trash2 size={16}/></button>
                              </div>
                              <p className="text-sm text-white/70 italic mb-6">"{review.comment}"</p>

                              {review.adminReply ? (
                                  <div className="bg-brand-orange/10 p-5 rounded-2xl border border-brand-orange/20">
                                      <p className="text-[10px] font-black text-brand-orange uppercase tracking-widest mb-2 flex items-center gap-2"><CheckCircle2 size={12}/> Réponse envoyée :</p>
                                      <p className="text-xs italic font-bold text-white/90">"{review.adminReply}"</p>
                                      <button onClick={() => { setReplyingToReview(review); setReplyText(review.adminReply || ''); }} className="mt-4 text-[9px] font-black uppercase text-brand-orange border-b border-brand-orange pb-1">Modifier ma réponse</button>
                                  </div>
                              ) : (
                                  <button onClick={() => setReplyingToReview(review)} className="flex items-center gap-2 bg-brand-orange text-white px-6 py-3 rounded-2xl text-[10px] font-black uppercase shadow-lg active:scale-95 transition-all">
                                      <MessageCircle size={14}/> Répondre à ce client
                                  </button>
                              )}
                          </div>
                      ))}
                  </div>
              </div>
          )}

          {/* DASHBOARD, PLATS, etc. (Contenu simplifié pour le focus REVIEWS) */}
          {currentView === AdminView.DASHBOARD && <div className="p-20 text-center text-white/20 font-black uppercase">Statistiques générales</div>}
          {currentView === AdminView.PLATS && <div className="p-20 text-center text-white/20 font-black uppercase">Gestion du menu</div>}
      </div>

      {/* MODAL RÉPONSE ADMIN */}
      {replyingToReview && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl animate-fade-in">
              <div className="bg-[#1A0F0D] rounded-[4rem] w-full max-w-md p-10 border border-white/10 shadow-2xl">
                  <div className="flex justify-between items-center mb-8">
                      <h3 className="text-xl font-black text-white uppercase italic">Votre Réponse ✨</h3>
                      <button onClick={() => setReplyingToReview(null)}><X/></button>
                  </div>
                  <div className="mb-6 p-4 bg-white/5 rounded-2xl italic text-[11px] text-white/50">
                      "{replyingToReview.comment}"
                  </div>
                  <textarea 
                    placeholder="Répondez à ce client avec élégance..." 
                    className="w-full p-6 bg-white/5 rounded-3xl outline-none font-bold text-sm text-white h-40 resize-none border border-white/10"
