                                      <div className="w-6 h-6 bg-brand-brown rounded-full flex items-center justify-center text-[10px] text-brand-gold font-black">K</div>
                                      <span className="text-[10px] font-black text-brand-orange uppercase tracking-widest italic">Réponse de Khady's</span>
                                  </div>
                                  <p className="text-[12px] text-brand-brown font-bold italic leading-relaxed">{review.adminReply}</p>
                              </div>
                          )}
                      </div>
                  ))}
               </div>
            </div>
          </div>
        );

      case Page.MENU:
      case Page.BOX:
      case Page.PACKS:
        const isBox = currentPage === Page.BOX;
        const isPack = currentPage === Page.PACKS;
        const filteredItems = items.filter(i => {
            if (isPack) return i.category === 'Pack';
            if (isBox) return i.category === 'Box';
            return i.category !== 'Pack' && i.category !== 'Box';
        });
        return (
            <div className="pb-32 animate-fade-in px-6 pt-10 max-w-6xl mx-auto w-full">
                <header className="mb-10 text-center">
                    <h2 className="text-4xl font-black text-brand-brown uppercase italic tracking-tighter">{isPack ? 'Packs Buffet' : isBox ? 'Box Sauces' : 'La Carte'}</h2>
                </header>
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                    {filteredItems.map(item => (
                        <div key={item.id} className="bg-white p-4 rounded-[3rem] shadow-xl flex flex-col cursor-pointer" onClick={() => setSelectedItemForDetails(item)}>
                            <img src={item.image} className="h-32 w-full object-cover rounded-2xl mb-4" />
                            <h4 className="text-[10px] font-black text-brand-brown uppercase mb-2 truncate">{item.name}</h4>
                            <div className="flex justify-between items-center mt-auto">
                                <span className="text-xs font-black text-brand-orange">{item.price} F</span>
                                <div className="w-8 h-8 bg-brand-brown text-brand-gold rounded-full flex items-center justify-center"><Plus size={14}/></div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        );

      case Page.TRAITEUR:
        return (
            <div className="pb-32 animate-fade-in px-6 pt-10 max-w-4xl mx-auto w-full">
