import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import AIChat from './components/AIChat';
import AdminDashboard from './components/AdminDashboard';
import DeliveryEstimator from './components/DeliveryEstimator';
import ItemDetailsModal from './components/ItemDetailsModal'; 
import { KhadyLogo } from './components/KhadyLogo';
import { playSound } from './utils/audio';
import { Page, MenuItem, CartItem, Review, MenuCategory } from './types';
import { MENU_ITEMS, REVIEWS as INITIAL_REVIEWS, ADMIN_PASSWORD, RESTAURANT_INFO, LOGO_VIDEO_URL, BILLO_INFO } from './constants';
import { 
  Plus, Star, User, Sparkles, ShoppingBag, Clock, Phone, Facebook, Instagram, Mail, Info, ChefHat, Calendar, Heart, Users, X, MessageCircle, Lock
} from 'lucide-react';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isReviewModalOpen, setIsReviewModalOpen] = useState(false);

  const [profile, setProfile] = useState({ name: '', phone: '', address: '', district: '', preferences: '' });
  const [items, setItems] = useState<MenuItem[]>(MENU_ITEMS);
  const [reviews, setReviews] = useState<Review[]>(INITIAL_REVIEWS);
  const [selectedItemForDetails, setSelectedItemForDetails] = useState<MenuItem | null>(null);
  const [featuredIndex, setFeaturedIndex] = useState(0);

  // Formulaire nouvel avis
  const [newReview, setNewReview] = useState({ name: '', rating: 5, comment: '', image: '' });

  useEffect(() => {
    const timer = setTimeout(() => setShowSplash(false), 4500); 
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      setFeaturedIndex((prev) => (prev + 1) % 4);
    }, 6000);
    return () => clearInterval(interval);
  }, []);

  const handleProfileSave = (e: React.FormEvent) => {
    e.preventDefault();
    playSound('success');
    alert('Profil mis à jour !');
  };

  const submitReview = (e: React.FormEvent) => {
    e.preventDefault();
    const review: Review = {
        id: Date.now().toString(),
        name: newReview.name || "Client Anonyme",
        rating: newReview.rating,
        comment: newReview.comment,
        image: newReview.image || "https://images.unsplash.com/photo-1531123897727-8f129e1688ce?auto=format&fit=crop&q=80&w=200",
        date: "À l'instant"
    };
    setReviews([review, ...reviews]);
    setIsReviewModalOpen(false);
    setNewReview({ name: '', rating: 5, comment: '', image: '' });
    playSound('success');
  };

  if (currentPage === Page.ADMIN) {
      return (
          <AdminDashboard 
            items={items} setItems={setItems} 
            reviews={reviews} setReviews={setReviews}
            onExit={() => setCurrentPage(Page.HOME)}
            adminPhoto={null} setAdminPhoto={() => {}}
            adminPhone="+227 00 00 00 00" setAdminPhone={() => {}}
            loyaltyConfig={{ pointsPerFranc: 1, rewardThreshold: 1000 }} setLoyaltyConfig={() => {}}
          />
      );
  }

  if (showSplash) {
    return (
      <div className="fixed inset-0 z-[100] bg-brand-brown flex items-center justify-center overflow-hidden">
        <video autoPlay muted playsInline className="w-full h-full object-cover opacity-90" onEnded={() => setShowSplash(false)}>
          <source src={LOGO_VIDEO_URL} type="video/mp4" />
        </video>
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/30 pointer-events-none">
          <KhadyLogo variant="light" className="scale-125 animate-pulse-slow" />
        </div>
      </div>
    );
  }

  const renderContent = () => {
    switch(currentPage) {
      case Page.HOME:
        return (
          <div className="pb-24 animate-fade-in w-full max-w-4xl mx-auto px-4">
            {/* 1. HEADER 👋🏾 */}
