                    <div className="relative w-full max-w-[340px] aspect-[4/5] mx-auto">
                        <div className="absolute inset-0 bg-white rounded-[4.5rem] shadow-2xl border-[16px] border-white overflow-hidden">
                            {items.filter(i => i.isPlatDuJour).slice(0,4).map((item, idx) => (
                              <div key={item.id} className={`absolute inset-0 transition-all duration-1000 ${idx === featuredIndex ? 'opacity-100' : 'opacity-0'}`} onClick={() => setSelectedItemForDetails(item)}>
                                <img src={item.image} className="w-full h-full object-cover" />
                                <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent"></div>
                                <div className="absolute bottom-12 left-8 right-8 text-white">
                                    <h3 className="text-2xl font-black uppercase italic mb-1">{item.name}</h3>
                                    <p className="text-brand-gold font-black text-xl">{item.price} CFA</p>
                                </div>
                              </div>
                            ))}
                        </div>
                        <button onClick={() => setSelectedItemForDetails(items.filter(i => i.isPlatDuJour)[featuredIndex])} className="absolute -bottom-4 -right-4 bg-brand-brown text-brand-gold w-16 h-16 rounded-[2.5rem] shadow-2xl flex items-center justify-center border-4 border-white active:scale-90 z-20"><Plus size={32} /></button>
                    </div>
                </div>
            </div>

            {/* 5. LIVRAISON */}
            <DeliveryEstimator />

            {/* 6. AVIS CLIENTS (RÉTABLISSEMENT DU FOND MARRON CHOCOLAT) */}
            <div className="mb-16 mt-20 px-2">
               <div className="flex justify-between items-center mb-8">
                   <h3 className="font-black text-2xl text-brand-brown uppercase italic tracking-tighter">🧡 La Voix des Clients</h3>
                   <button onClick={() => setIsReviewModalOpen(true)} className="bg-brand-orange text-white px-4 py-2 rounded-2xl text-[10px] font-black uppercase flex items-center gap-2 shadow-lg active:scale-95 transition-all">✨ Donner mon avis</button>
               </div>

               <div className="grid grid-cols-1 gap-8">
                  {reviews.map(review => (
                      <div key={review.id} className="bg-brand-brown rounded-[3rem] p-8 shadow-2xl border border-white/5 relative overflow-hidden group">
                          {/* Décoration subtile en arrière-plan */}
                          <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -mr-16 -mt-16 group-hover:scale-110 transition-transform duration-700"></div>

                          <div className="flex gap-6 mb-6 relative z-10">
                              <img src={review.image} className="w-16 h-16 rounded-full border-2 border-brand-orange object-cover shadow-xl flex-shrink-0" />
                              <div className="flex-1">
                                  <div className="flex justify-between items-start">
                                      <p className="font-black text-sm text-brand-gold uppercase tracking-widest">{review.name}</p>
                                      <span className="text-[10px] font-bold text-white/30 uppercase tracking-tighter">{review.date}</span>
                                  </div>
                                  <div className="flex gap-0.5 mb-3">{[...Array(review.rating)].map((_, i) => <Star key={i} size={12} fill="#FFD700" color="#FFD700" />)}</div>
