import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import AIChat from './components/AIChat';
import AdminDashboard from './components/AdminDashboard';
import DeliveryEstimator from './components/DeliveryEstimator';
import ItemDetailsModal from './components/ItemDetailsModal'; 
import { KhadyLogo } from './components/KhadyLogo';
import { playSound } from './utils/audio';
import { Page, MenuItem, CartItem, Review, MenuCategory } from './types';
import { MENU_ITEMS, REVIEWS as INITIAL_REVIEWS, ADMIN_PASSWORD, RESTAURANT_INFO, LOGO_VIDEO_URL, BILLO_INFO } from './constants';
import { 
  Plus, Star, User, Sparkles, ShoppingBag, Clock, Phone, Facebook, Instagram, Mail, Info, ChefHat, Calendar, Heart, Users, X, MessageCircle, Lock
} from 'lucide-react';

const App: React.FC = () => {
  const [showSplash, setShowSplash] = useState(true);
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [isReviewModalOpen, setIsReviewModalOpen] = useState(false);

  const [profile, setProfile] = useState({ name: '', phone: '', address: '', district: '', preferences: '' });
  const [items, setItems] = useState<MenuItem[]>(MENU_ITEMS);
  const [reviews, setReviews] = useState<Review[]>(INITIAL_REVIEWS);
  const [selectedItemForDetails, setSelectedItemForDetails] = useState<MenuItem | null>(null);
  const [featuredIndex, setFeaturedIndex] = useState(0);

  const [newReview, setNewReview] = useState({ name: '', rating: 5, comment: '', image: '' });

  useEffect(() => {
    const timer = setTimeout(() => setShowSplash(false), 4500); 
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      setFeaturedIndex((prev) => (prev + 1) % 4);
    }, 6000);
    return () => clearInterval(interval);
  }, []);

  const handleProfileSave = (e: React.FormEvent) => {
    e.preventDefault();
    playSound('success');
    alert('Profil mis à jour !');
  };

  const submitReview = (e: React.FormEvent) => {
    e.preventDefault();
    const review: Review = {
        id: Date.now().toString(),
        name: newReview.name || "Client Anonyme",
        rating: newReview.rating,
        comment: newReview.comment,
        image: newReview.image || "https://images.unsplash.com/photo-1531123897727-8f129e1688ce?auto=format&fit=crop&q=80&w=200",
        date: "À l'instant"
    };
    setReviews([review, ...reviews]);
    setIsReviewModalOpen(false);
    setNewReview({ name: '', rating: 5, comment: '', image: '' });
    playSound('success');
  };

  if (currentPage === Page.ADMIN) {
      return (
          <AdminDashboard 
            items={items} setItems={setItems} 
            reviews={reviews} setReviews={setReviews}
            onExit={() => setCurrentPage(Page.HOME)}
            adminPhoto={null} setAdminPhoto={() => {}}
            adminPhone="+227 00 00 00 00" setAdminPhone={() => {}}
            loyaltyConfig={{ pointsPerFranc: 1, rewardThreshold: 1000 }} setLoyaltyConfig={() => {}}
          />
      );
  }

  if (showSplash) {
    return (
      <div className="fixed inset-0 z-[100] bg-brand-brown flex items-center justify-center overflow-hidden">
        <video autoPlay muted playsInline className="w-full h-full object-cover opacity-90" onEnded={() => setShowSplash(false)}>
          <source src={LOGO_VIDEO_URL} type="video/mp4" />
        </video>
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/30 pointer-events-none">
          <KhadyLogo variant="light" className="scale-125 animate-pulse-slow" />
        </div>
      </div>
    );
  }

  const renderContent = () => {
    switch(currentPage) {
      case Page.HOME:
        return (
          <div className="pb-24 animate-fade-in w-full max-w-4xl mx-auto px-4">
            {/* 1. HEADER 👋🏾 */}
            <div className="flex justify-between items-center py-6 bg-brand-cream sticky top-0 z-30 shadow-sm border-b border-brand-brown/5 rounded-b-3xl">
              <div className="scale-90 sm:scale-100 origin-left ml-2">
                <KhadyLogo />
              </div>
              <div className="flex items-center gap-4 mr-2">
                <div className="flex flex-col items-end">
                    <span className="text-[9px] font-black text-brand-brown/30 uppercase tracking-[0.2em] mb-0.5">Bienvenue</span>
                    <div className="flex items-center gap-2">
                        <span className="text-xs font-black text-brand-brown italic">Bonjour</span>
                        <span className="text-xl animate-wave origin-bottom-right inline-block">👋🏾</span>
                    </div>
                </div>
                <button onClick={() => setCurrentPage(Page.COMPTE)} className="w-12 h-12 rounded-full bg-brand-brown/10 flex items-center justify-center border-2 border-brand-brown/20 overflow-hidden shadow-lg active:scale-90 transition-all">
                  <User size={24} className="text-brand-brown" />
                </button>
              </div>
            </div>

            {/* 2. DÉFILEMENT DES PLATS (REPLACÉ À SA POSITION INITIALE SOUS LE HEADER) */}
            <div className="py-8 bg-white overflow-hidden w-full relative rounded-[3.5rem] shadow-xl border border-gray-50 mt-6 mb-6">
                <div className="relative flex overflow-x-hidden">
                    <div className="flex animate-marquee whitespace-nowrap gap-6 py-4 px-4">
                        {[...items.filter(i => i.isPlatDuJour), ...items.filter(i => i.isPlatDuJour)].map((item, i) => (
                            <div key={i} className="inline-block w-48 h-48 rounded-[3rem] overflow-hidden shadow-2xl flex-shrink-0 cursor-pointer relative group transition-transform hover:scale-105" onClick={() => setSelectedItemForDetails(item)}>
                                <img src={item.image} className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-110" loading="lazy" />
                                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent opacity-60"></div>
                                <div className="absolute bottom-6 left-6 right-6 text-white whitespace-normal text-center">
                                    <h4 className="font-black text-[10px] uppercase leading-tight">{item.name}</h4>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* 3. HERO TITLE */}
            <div className="px-2 py-6 text-center sm:text-left">
                <h1 className="text-4xl sm:text-5xl font-black text-brand-brown leading-none uppercase tracking-tighter italic">L'Art Culinaire <br/><span className="text-brand-orange">Africain Premium</span></h1>
            </div>

            {/* 4. COUP DE COEUR */}
            <div className="mb-16 animate-slide-up">
                <div className="px-4 mb-8">
                    <h3 className="font-black text-2xl text-brand-brown uppercase italic tracking-tighter flex items-center gap-3">
                      <Sparkles className="text-brand-orange" size={24} /> Coup de Coeur
                    </h3>
                </div>
                <div className="py-6 flex flex-col items-center w-full">
                    <div className="relative w-full max-w-[340px] aspect-[4/5] mx-auto">
                        <div className="absolute inset-0 bg-white rounded-[4.5rem] shadow-2xl border-[16px] border-white overflow-hidden">
                            {items.filter(i => i.isPlatDuJour).slice(0,4).map((item, idx) => (
                              <div key={item.id} className={`absolute inset-0 transition-all duration-1000 ${idx === featuredIndex ? 'opacity-100' : 'opacity-0'}`} onClick={() => setSelectedItemForDetails(item)}>
                                <img src={item.image} className="w-full h-full object-cover" />
                                <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent"></div>
                                <div className="absolute bottom-12 left-8 right-8 text-white">
                                    <h3 className="text-2xl font-black uppercase italic mb-1">{item.name}</h3>
                                    <p className="text-brand-gold font-black text-xl">{item.price} CFA</p>
                                </div>
                              </div>
                            ))}
                        </div>
                        <button onClick={() => setSelectedItemForDetails(items.filter(i => i.isPlatDuJour)[featuredIndex])} className="absolute -bottom-4 -right-4 bg-brand-brown text-brand-gold w-16 h-16 rounded-[2.5rem] shadow-2xl flex items-center justify-center border-4 border-white active:scale-90 z-20"><Plus size={32} /></button>
                    </div>
                </div>
            </div>

            {/* 5. LIVRAISON */}
            <DeliveryEstimator />

            {/* 6. AVIS CLIENTS (RETOUR DU FOND MARRON CHOCOLAT DÉFINITIF) */}
            <div className="mb-16 mt-20 px-2">
               <div className="flex justify-between items-center mb-8">
                   <h3 className="font-black text-2xl text-brand-brown uppercase italic tracking-tighter">🧡 La Voix des Clients</h3>
                   <button onClick={() => setIsReviewModalOpen(true)} className="bg-brand-orange text-white px-4 py-2 rounded-2xl text-[10px] font-black uppercase flex items-center gap-2 shadow-lg active:scale-95 transition-all">✨ Donner mon avis</button>
               </div>

               <div className="grid grid-cols-1 gap-8">
                  {reviews.map(review => (
                      <div key={review.id} className="bg-brand-brown rounded-[3rem] p-8 shadow-2xl border border-white/5 relative overflow-hidden group">
                          {/* Décoration subtile en arrière-plan */}
                          <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -mr-16 -mt-16 group-hover:scale-110 transition-transform duration-700"></div>

                          <div className="flex gap-6 mb-6 relative z-10">
                              <img src={review.image} className="w-16 h-16 rounded-full border-2 border-brand-orange object-cover shadow-xl flex-shrink-0" />
                              <div className="flex-1">
                                  <div className="flex justify-between items-start">
                                      <p className="font-black text-sm text-brand-gold uppercase tracking-widest">{review.name}</p>
                                      <span className="text-[10px] font-bold text-white/30 uppercase tracking-tighter">{review.date}</span>
                                  </div>
                                  <div className="flex gap-0.5 mb-3">{[...Array(review.rating)].map((_, i) => <Star key={i} size={12} fill="#FFD700" color="#FFD700" />)}</div>
                                  <p className="text-[13px] text-brand-cream italic font-medium leading-relaxed">"{review.comment}"</p>
                              </div>
                          </div>

                          {review.adminReply && (
                              <div className="ml-12 bg-black/30 border-l-4 border-brand-orange p-5 rounded-2xl animate-fade-in relative z-10 shadow-inner">
                                  <div className="flex items-center gap-2 mb-2">
                                      <div className="w-6 h-6 bg-brand-orange rounded-full flex items-center justify-center text-[10px] text-white font-black shadow-lg">K</div>
                                      <span className="text-[10px] font-black text-brand-orange uppercase tracking-[0.2em] italic">Réponse de Khady's</span>
                                  </div>
                                  <p className="text-[12px] text-white/90 font-bold italic leading-relaxed">{review.adminReply}</p>
                              </div>
                          )}
                      </div>
                  ))}
               </div>
            </div>
          </div>
        );

      case Page.MENU:
      case Page.BOX:
      case Page.PACKS:
        const isBox = currentPage === Page.BOX;
        const isPack = currentPage === Page.PACKS;
        const filteredItems = items.filter(i => {
            if (isPack) return i.category === 'Pack';
            if (isBox) return i.category === 'Box';
