              <div className="pb-32 animate-fade-in px-6 pt-10 max-w-lg mx-auto w-full">
                  <div className="bg-white rounded-[4rem] shadow-2xl p-10 space-y-10">
                      <div className="text-center"><KhadyLogo className="mb-8" /><p className="text-xs text-gray-500 font-medium italic">"{RESTAURANT_INFO.description}"</p></div>
                      <div className="space-y-4">
                          <h4 className="text-[10px] font-black text-brand-orange uppercase tracking-[0.3em]">Horaires</h4>
                          <div className="bg-brand-cream/30 p-4 rounded-2xl text-[11px] font-black text-brand-brown space-y-1">
                              <p>Lun - Sam : 08h - 22h</p><p className="text-brand-orange">Dimanche : 10h - 21h</p>
                          </div>
                      </div>
                      <div className="flex justify-center gap-6">
                        <Facebook size={24} className="text-brand-brown" />
                        <Instagram size={24} className="text-brand-brown" />
                        <Mail size={24} className="text-brand-brown" />
                      </div>
                  </div>
              </div>
          );

      case Page.CART:
        return (
          <div className="pb-24 animate-fade-in px-6 pt-10 max-w-4xl mx-auto w-full text-center">
              <header className="mb-10 flex justify-between items-center"><h2 className="text-3xl font-black text-brand-brown uppercase italic">Mon Panier</h2><ShoppingBag size={28}/></header>
              <div className="py-20 bg-white rounded-[4rem] font-black text-brand-brown italic uppercase tracking-widest opacity-30">Votre panier est vide...</div>
          </div>
        );

      default:
         return null;
    }
  };

  return (
    <div className="min-h-screen bg-brand-cream/10 shadow-2xl overflow-hidden relative font-sans flex flex-col items-center">
      <div className="flex-1 overflow-y-auto no-scrollbar scroll-smooth flex flex-col items-center w-full">
        <div className="w-full">{renderContent()}</div>
      </div>
      <Navbar currentPage={currentPage} setPage={setCurrentPage} cartCount={cart.length} />
      <AIChat />

      {/* MODAL LAISSER UN AVIS CLIENT */}
      {isReviewModalOpen && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-xl animate-fade-in">
              <div className="bg-white rounded-[3rem] w-full max-w-sm p-10 shadow-2xl">
                  <div className="flex justify-between items-center mb-8">
                      <h3 className="text-xl font-black text-brand-brown uppercase italic">Votre Avis ✨</h3>
                      <button onClick={() => setIsReviewModalOpen(false)}><X/></button>
                  </div>
                  <form onSubmit={submitReview} className="space-y-6">
                      <div>
                          <label className="text-[10px] font-black uppercase text-gray-400 block mb-2">Note sur 5</label>
                          <div className="flex gap-2">
                              {[1,2,3,4,5].map(n => (
                                  <button key={n} type="button" onClick={() => setNewReview({...newReview, rating: n})} className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${newReview.rating >= n ? 'bg-brand-orange text-white' : 'bg-gray-100 text-gray-400'}`}><Star size={20} fill={newReview.rating >= n ? "currentColor" : "none"} /></button>
                              ))}
                          </div>
                      </div>
                      <input required type="text" placeholder="Votre Prénom" className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold" value={newReview.name} onChange={e => setNewReview({...newReview, name: e.target.value})} />
                      {/* Fix: use setNewReview instead of setReview */}
                      <textarea required placeholder="Votre expérience culinaire..." className="w-full p-4 bg-gray-50 rounded-2xl outline-none font-bold h-24 resize-none" value={newReview.comment} onChange={e => setNewReview({...newReview, comment: e.target.value})} />
                      <button type="submit" className="w-full bg-brand-brown text-brand-gold py-5 rounded-2xl font-black uppercase shadow-xl active:scale-95 transition-all">Publier mon avis</button>
                  </form>
              </div>
          </div>
      )}

      <ItemDetailsModal 
        item={selectedItemForDetails} 
        isOpen={!!selectedItemForDetails} 
        onClose={() => setSelectedItemForDetails(null)} 
        onAddToCart={(item, qty, inst) => { 
          setCart([...cart, {...item, quantity: qty, instructions: inst}]); 
          playSound('success'); 
        }} 
      />
    </div>
  );
};

export default App;
